mapper.select:
SELECT WM_CONCAT(`name`)
SELECT GROUP_CONCAT(`name`)
FROM `conference_device` where conference_id = #{conferenceId}

SELECT b.`time_interval` `timeInterval`, b.`conference_id` `conferenceId`, b.`book_id` `bookId`, a.`status` FROM `book_room` a LEFT JOIN `book_interval_record` b on a.`id` = b.`book_id` WHERE a.`status` != 'CANCEL_RESERVATION'
and b.`appointment_date` = to_timestamp(#{date},'yyyy-MM-dd hh24:mi:ss')
and b.`appointment_date` = #{date}
and b.`conference_id` in
#{item}
